+@page "/track"
+@using Microsoft.AspNetCore.Authorization
+@using Microsoft.AspNetCore.Components.Authorization
+@using ShipmentTracker.Client.Models
+@using ShipmentTracker.Client.Services
+@attribute [Authorize]
+@inject IShipmentService ShipmentService
+@inject AuthenticationStateProvider AuthStateProvider
+
+<PageTitle>Track My Shipments</PageTitle>
+
+<h1>Track My Shipments</h1>
+
+<div class="mb-3">
+    <label class="form-label">Search by Tracking Number</label>
+    <div class="input-group">
+        <input type="text" class="form-control" placeholder="Enter tracking number..."
+               @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
+        <button class="btn btn-primary" @onclick="SearchByTracking">Search</button>
+    </div>
+</div>
+
+@if (searchedShipment is not null)
+{
+    <div class="card mb-4">
+        <div class="card-header">
+            <strong>@searchedShipment.TrackingNumber</strong>
+        </div>
+        <div class="card-body">
+            <dl class="row mb-0">
+                <dt class="col-sm-4">Status</dt>
+                <dd class="col-sm-8">
+                    <span class="badge @GetStatusBadgeClass(searchedShipment.Status)">
+                        @searchedShipment.Status
+                    </span>
+                </dd>
+                <dt class="col-sm-4">Origin</dt>
+                <dd class="col-sm-8">@searchedShipment.Origin</dd>
+                <dt class="col-sm-4">Destination</dt>
+                <dd class="col-sm-8">@searchedShipment.Destination</dd>
+                <dt class="col-sm-4">Estimated Delivery</dt>
+                <dd class="col-sm-8">@(searchedShipment.EstimatedDelivery?.ToString("MMMM dd, yyyy") ?? "TBD")</dd>
+                <dt class="col-sm-4">Description</dt>
+                <dd class="col-sm-8">@searchedShipment.Description</dd>
+            </dl>
+        </div>
+    </div>
+}
+else if (searchPerformed)
+{
+    <div class="alert alert-warning">No shipment found with that tracking number.</div>
+}
+
+<hr />
+
+<h2>My Shipments</h2>
+
+@if (myShipments is null)
+{
+    <p><em>Loading your shipments...</em></p>
+}
+else if (!myShipments.Any())
+{
+    <p>You have no shipments on record.</p>
+}
+else
+{
+    <div class="row">
+        @foreach (var shipment in myShipments)
+        {
+            <div class="col-md-6 mb-3">
+                <div class="card">
+                    <div class="card-body">
+                        <h5 class="card-title">@shipment.TrackingNumber</h5>
+                        <p class="card-text">
+                            <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span><br />
+                            <strong>To:</strong> @shipment.Destination<br />
+                            <strong>Est. Delivery:</strong> @(shipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "TBD")
+                        </p>
+                    </div>
+                </div>
+            </div>
+        }
+    </div>
+}
+
+@code {
+    private string trackingNumber = string.Empty;
+    private Shipment? searchedShipment;
+    private bool searchPerformed;
+    private List<Shipment>? myShipments;
+
+    protected override async Task OnInitializedAsync()
+    {
+        var authState = await AuthStateProvider.GetAuthenticationStateAsync();
+        var email = authState.User.Identity?.Name ?? string.Empty;
+        if (!string.IsNullOrEmpty(email))
+        {
+            myShipments = await ShipmentService.GetShipmentsForCustomerAsync(email);
+        }
+        else
+        {
+            myShipments = [];
+        }
+    }
+
+    private async Task SearchByTracking()
+    {
+        searchPerformed = true;
+        if (!string.IsNullOrWhiteSpace(trackingNumber))
+        {
+            searchedShipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
+        }
+        else
+        {
+            searchedShipment = null;
+        }
+    }
+
+    private async Task HandleKeyDown(KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter")
+        {
+            await SearchByTracking();
+        }
+    }
+
+    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Delivered => "bg-success",
+        ShipmentStatus.InTransit => "bg-primary",
+        ShipmentStatus.OutForDelivery => "bg-info",
+        ShipmentStatus.Delayed => "bg-danger",
+        ShipmentStatus.PickedUp => "bg-warning text-dark",
+        _ => "bg-secondary"
+    };
+}
+

