```

Create `ShipmentTracker/Services/ShipmentServerService.cs`:
```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServerService(IDbContextFactory<ApplicationDbContext> contextFactory) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        await using var context = await contextFactory.CreateDbContextAsync();
        return await context.Shipments
            .OrderByDescending(s => s.CreatedAt)
            .Select(s => ToModel(s))
            .ToListAsync();
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        await using var context = await contextFactory.CreateDbContextAsync();
        var entity = await context.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return entity is null ? null : ToModel(entity);
    }

    public async Task<List<Shipment>> GetShipmentsForCustomerAsync(string email)
    {
        await using var context = await contextFactory.CreateDbContextAsync();
        return await context.Shipments
            .Where(s => s.CustomerEmail == email)
            .OrderByDescending(s => s.CreatedAt)
            .Select(s => ToModel(s))
            .ToListAsync();
    }

    public async Task<Shipment> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        await using var context = await contextFactory.CreateDbContextAsync();
        var entity = await context.Shipments.FindAsync(id)
            ?? throw new InvalidOperationException($"Shipment {id} not found.");
        entity.Status = status;
        await context.SaveChangesAsync();
        return ToModel(entity);
    }

    private static Shipment ToModel(ShipmentEntity entity) => new()
    {
        Id = entity.Id,
        TrackingNumber = entity.TrackingNumber,
        Origin = entity.Origin,
        Destination = entity.Destination,
        Status = entity.Status,
        EstimatedDelivery = entity.EstimatedDelivery,
        CreatedAt = entity.CreatedAt,
        CustomerEmail = entity.CustomerEmail,
        Description = entity.Description
    };
}
```

